-- ============================================================================
-- Graduation module: credit units, earlier graduations, harmonised checks
-- 31 October 2026. Everything below was executed on the live database that day;
-- the file is idempotent and can be replayed.
--
-- PART 1  acad_graduands_prior: the 1,607 graduation records as they stood at
--         12:10 on 25 Sep 2026, from COOPERP/backups/acad_graduands-full-before-
--         wipe-20260925-121057.sql. acad_graduands was emptied after that dump,
--         and without these rows C1 could not see that someone had graduated
--         (190 such people in the 2026/2027 queue, 243 holds reading "she/he
--         graduated", 10 approved a second time). Read-only reference; nothing
--         in the application writes to it.
-- PART 2  acad_grad_stats: seven columns the engine reads. The application adds
--         them itself if missing (GraduationStats.EnsureSchema); listed for the
--         record. Run the Graduation Centre's Refresh afterwards to fill them.
-- PART 3  Four graded results with NULL CreditUnits where the catalogue and
--         15 of 17 other results for the course carry 3; stored semester gpa
--         recomputed for the four semesters touched. Backup + rollback included.
-- ============================================================================
USE campus_dynamics;

-- PART 1 ---------------------------------------------------------------------
SET NAMES utf8;
CREATE TABLE IF NOT EXISTS acad_graduands_prior (
  prior_id INT UNSIGNED NOT NULL COMMENT 'acad_graduands.ID in the dump',
  regno CHAR(25) NOT NULL,
  acadyear CHAR(25) NOT NULL,
  cgpa DOUBLE NULL,
  degclass VARCHAR(150) NULL,
  stud_name VARCHAR(65) NULL,
  progcode CHAR(25) NULL,
  trans_status VARCHAR(45) NULL,
  cert_status VARCHAR(45) NULL,
  grad_date DATE NULL,
  comp_date DATE NULL,
  convocation VARCHAR(200) NULL,
  PRIMARY KEY (prior_id),
  KEY ix_prior_regno (regno)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci
  COMMENT='Graduation records as they stood at 2026-09-25 12:10 (COOPERP/backups/acad_graduands-full-before-wipe-20260925-121057.sql). Read-only reference.';

-- PART 2 ---------------------------------------------------------------------
-- (Skip if the columns exist; GraduationStats.EnsureSchema adds any that are missing.)
-- ALTER TABLE acad_grad_stats
