--  ADD COLUMN term_mask INT NOT NULL DEFAULT 0 COMMENT 'bit (studyyear-1)*3+(semester-1) per term with results',
--  ADD COLUMN pend_rt INT NOT NULL DEFAULT 0 COMMENT 'retakes registered, result blanked, not yet marked',
--  ADD COLUMN dup_n INT NOT NULL DEFAULT 0 COMMENT 'courses on record twice: same code bar spaces, same title',
--  ADD COLUMN dup_cu DOUBLE NOT NULL DEFAULT 0 COMMENT 'credits counted twice by those duplicates',
--  ADD COLUMN dup_fail INT NOT NULL DEFAULT 0 COMMENT 'fails superseded by, or duplicating, the other copy',
--  ADD COLUMN cap_mask INT NOT NULL DEFAULT 0 COMMENT 'passed final-year components: 1 research, 2 school practice, 4 internship';

-- PART 3 ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS bak_gradcufix_20261031 ENGINE=InnoDB AS
  SELECT r.* FROM acad_results r
  JOIN (SELECT regno, studyyear, semester FROM acad_results WHERE ID IN (607080,624833,646216,648069)) k
    ON k.regno=r.regno AND k.studyyear=r.studyyear AND k.semester=r.semester;
START TRANSACTION;
UPDATE acad_results r JOIN acad_course c ON c.courseID=r.courseid
   SET r.CreditUnits = c.CreditUnit
 WHERE r.ID IN (607080,624833,646216,648069) AND r.CreditUnits IS NULL AND c.CreditUnit = 3;
UPDATE acad_results r
  JOIN (SELECT r2.regno, r2.studyyear, r2.semester,
               ROUND(SUM(r2.gradept*r2.CreditUnits)/NULLIF(SUM(r2.CreditUnits),0),2) g
          FROM acad_results r2
          JOIN (SELECT DISTINCT regno, studyyear, semester FROM bak_gradcufix_20261031) k
            ON k.regno=r2.regno AND k.studyyear=r2.studyyear AND k.semester=r2.semester
         GROUP BY 1,2,3) s ON s.regno=r.regno AND s.studyyear=r.studyyear AND s.semester=r.semester
   SET r.gpa = s.g;
COMMIT;
-- Result on 31 Oct 2026: MRU2022000296 y2s1 4.80 -> 4.73, MRU2022000555 y3s1 4.00 -> 4.10,
-- MRU2022000903 y3s1 4.40 -> 4.42, MRU2023001021 y2s1 4.50 (unchanged). No class changed.
